<script>
// Mega menu toggle
function toggleMenu(e, menuId) {
  e.preventDefault();
  const items = document.querySelectorAll('.nav-item');
  items.forEach(item => {
    if (item.dataset.menu === menuId) {
      item.classList.toggle('active');
    } else {
      item.classList.remove('active');
    }
  });
}

document.addEventListener('click', function(e) {
  if (!e.target.closest('.nav-item')) {
    document.querySelectorAll('.nav-item').forEach(i => i.classList.remove('active'));
  }
});

// Health topics carousel
function scrollCarousel(dir) {
  const track = document.getElementById('topicsCarousel');
  track.scrollBy({ left: dir * 200, behavior: 'smooth' });
}

// Recommended reads tabs
function switchTab(e, cat) {
  document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
  e.target.classList.add('active');

  const cards = document.querySelectorAll('#articlesGrid .article-card');
  cards.forEach(card => {
    const cats = card.dataset.cats.split(',');
    if (cat === 'all' || cats.includes(cat)) {
      card.style.display = '';
      card.style.animation = 'fadeIn 0.3s ease';
    } else {
      card.style.display = 'none';
    }
  });
}

// Fade-in animation for tab switch
const style = document.createElement('style');
style.textContent = '@keyframes fadeIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}';
document.head.appendChild(style);
</script>

